package rw.isurafashion.controller;
import rw.isurafashion.service.AuthService; import rw.isurafashion.security.TokenBlacklist; import rw.isurafashion.security.JwtService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth; private final TokenBlacklist blacklist; private final JwtService jwt; public AuthController(AuthService a,TokenBlacklist b,JwtService j){auth=a;blacklist=b;jwt=j;} @PostMapping("/register") public Map<String,Object> register(@RequestBody Map<String,String> b){return auth.register(b.get("email"),b.get("password"),b.get("phone"));} @PostMapping("/login") public Map<String,Object> login(@RequestBody Map<String,String> b){return auth.login(b.get("email"),b.get("password"));} @PostMapping("/logout") public Map<String,String> logout(@RequestHeader(value="Authorization",required=false) String h){if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);try{blacklist.revoke(t,jwt.parse(t).getExpiration().toInstant());}catch(Exception ignored){}} return Map.of("message","Logged out");}}
